[ "$rc" = 2 ] || { echo "usage should exit 2"; fail=1; }
[ -z "$out" ] || { echo "usage should print nothing to stdout: $out"; fail=1; }
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\ty\naoi\t2026-01-05\t09:00\t10:00\tx\n' > "$t2"
